class Account:
    def __init__(self, balance=0):
        self.balance = balance

    def deposit(self, amount):
        self.balance += amount

    def withdraw(self, amount):
        if amount > self.balance:
            raise ValueError("недостаточно средств")
        self.balance -= amount


def run(operations):
    acc = Account()
    try:
        for kind, amount in operations:
            if kind == "d":
                acc.deposit(amount)
            else:
                acc.withdraw(amount)
    except ValueError:
        return "ошибка"
    return acc.balance

